import React from 'react'
import ReactDOM from 'react-dom';
import logo from './images/logo.png';
import './Login.scss'


export default function Login() {
  return (
    <div className='login'>
        <div className="header">
          <a href='#' className='login-logo'><img src={logo} alt="logo"/></a><div className='logo-btns'><a href="#" className='login-btn login'>Login</a><a href="#" className='login-btn registration-b'>Registration</a></div>
        </div>
    </div>
  )
}
